local _, WFI = ...
WFI.Data.add("quest", {
  [95041] = { "Accumulatori di dati", "Raccogli 7 schede di Gnomeregan Archival Data in giro per Gnomeregan, poi consegnale a Jemma Quikswitch, a Ironforge.", "Prima di fuggire da Gnomeregan ho fatto una copia cartacea degli archivi della mia famiglia. Equazioni di campo arcanotecniche, progetti di scafi di sottomarini della Second War, la ricetta del chili di nonna Quikswitch... le nostre più grandi conquiste sono in quei file.\n\nSolo quando siamo arrivati a Ironforge ho scoperto un buco nello zaino! Mancano diverse schede perforate, e senza di esse i dati sono troppo confusi per essere recuperati.\n\nLe schede devono essere sepolte nella neve, da qualche parte fuori Gnomeregan. Potresti trovarle? So che è un tentativo disperato...", "Come procede il recupero dei dati?", "Queste schede sembrano un po' umide... ma posso lavorarci! Grazie, {name}!", 0x2ec708ec, 0xdde3bae7, 0xd738032b, 0x4bbba72e, 0x87fa01c3, "....." },
  [95042] = { "In cerca della Kor Gem", "Porta una Kor Gem a Ulric Frostveil, ad Ashenvale.", "<Un/Una> <paladino/paladina> Forsaken... qui ad Ashenvale? Divertente.\n\nQuindi cerchi una Kor Gem? Non mi sorprende, visto che a volte i paladini dell'Alliance le usano per potenziare armi e strumenti magici. Perché <un/una> <paladino/paladina> <caduto/caduta> come te dovrebbe essere diverso?\n\nSe desideri davvero una di queste gemme, devi andare a nord, alle rovine note come Blackfathom Deeps. I naga che usano ancora le gemme sono laggiù. Non andarci da <solo/sola>, {class}.", "Le Kor gem possono essere usate per grandi atti di malvagità. Non sta a me giudicare se le tue intenzioni sono pure. Non m'importa.", "Noterai senza dubbio la corruzione che permea questa gemma. Per i tuoi scopi, la magia necessaria a dissipare il male che le streghe naga vi hanno infuso è piuttosto semplice. Un peccato davvero: si potrebbe imparare molto da simili poteri.\n\nImmagino che non saresti <disposto/disposta> ad abbandonare la missione che ti ha spinto a cercare questa gemma e a vendermela invece? Potrebbe rivelarsi preziosa per i miei... interessi accademici.", 0x5d353131, 0x653f65b8, 0x34bb9815, 0x3e8b8507, 0x8c1b448d, "....." },
  [95065] = { "È ora di pescare", "Porta $N1 Shiny Bauble e $N2 Nightcrawlers a Gilbert Gray, al porto di Stormwind.", "Che vista... Il meglio che un vecchio possa chiedere.\n\nI pesci abboccano proprio adesso, ma ho finito le esche. Immagino che tu non abbia con te dell'attrezzatura da pesca in più? Certo che no, perdonami. Mi emoziono così tanto all'idea di lanciare un'altra lenza che non mi è venuto in mente che forse sono uno dei pochi a portarsi dietro l'attrezzatura ovunque vada.\n\nPotresti aiutarmi a rifornirmi? Catherine Leland ha un assortimento di articoli da pesca appena a ovest del Trade District, lungo i canali. Dille che ti manda il vecchio Gray.", "Hai preso l'attrezzatura da pesca?", "Tempismo perfetto! Ho preso un pesce grosso con la mia ultima esca. Finora una gran bella giornata. Qui abboccano davvero!\n\nTi dico una cosa: visto che sei <stato/stata> così gentile da tenere in attività questo vecchio, che ne dici di qualche pesce per il viaggio?", 0x50ff1618, 0x1ca3ae56, 0x4f6c7d2d, 0x630eca56, 0x7cc547b8, "....." },
  [95161] = { "Ricorda che ti amo", "Consegna la Blood-Stained Letter ad Avette Fellwood, a Duskwood.", "Se cerchi Jeremy Heartweaver, la cosa migliore è parlare con la sua nuova madre adottiva, Avette Fellwood, a Duskwood. Una donna dolce. Probabilmente le serve un altro paio di mani per il suo lavoro, ma è meglio che restare all'orfanotrofio.\n\nSe vedi il piccolo Jeremy, digli che pensiamo tutti a lui, va bene?", "Sì? Di cosa hai bisogno?", "Oh no...\n\nÈ gentile da parte tua portarmela, ma non credo che Jeremy sia pronto a vederla. La Matron Nightingale ha detto che il mio piccolo Jeremy non parla dall'attacco a Lordaeron, e non intendo forzarlo adesso. Mostrargli questa gli causerebbe solo altro dolore.\n\nNon guardarmi così. Non gli nasconderò il suo passato, ma ha bisogno di tempo per guarire. Gliela darò quando sarà più grande. Grazie di essere <passato/passata>, ma credo sia ora che tu vada.", 0x920a601f, 0xa5aac85c, 0xab5e3e2b, 0x664e4a5c, 0xbb9d2166, "....." },
  [95189] = { nil, "Restituisci il Crest of Lordaeron a Lady Dena Kennedy, a Stormwind City.", "<Uno stemma consumato che raffigura il marchio di Lordaeron. Con così poche reliquie rimaste dopo la caduta del regno, qualcuno a Stormwind sarebbe molto desideroso di metterci le mani sopra.>", nil, nil, nil, 0xea3f7a39, 0x6f2a4873, nil, nil, "m..mm" },
  [95195] = { nil, "Raccogli $N1 Bloodied Insignias e portale al General Marcus Jonathan, a Stormwind City.", "<La vecchia insegna dell'Alliance sembra appartenuta a un soldato di Lordaeron. Probabilmente queste rovine sono piene di medaglie simili che i parenti in vita sarebbero grati di riavere.>", "Sembri portare un fardello pesante, {name}. Di cosa si tratta?", "Il tuo istinto di portarmeli non era infondato. Quando Lordaeron cadde per mano della Scourge, molti fuggirono a cercare rifugio qui a Stormwind. Probabilmente restano in pochi a reclamare di persona queste insegne.\n\nIl tuo senso del dovere verso Stormwind è encomiabile, {name}. Comincerò subito a distribuire queste insegne ai parenti più stretti.", nil, 0xf9dfef5a, 0x2c958367, 0x3d6daf5e, 0x351f4fdf, "m...." },
  [95350] = { "<Benvenuto/Benvenuta> su Azeroth", nil, nil, nil, nil, 0x2f003d6f, nil, nil, nil, nil, ".mmmm" },
  [95494] = { nil, nil, nil, "Come va la caccia?", nil, nil, nil, nil, 0xe02b27bb, nil, "mmm.m" },
  [95495] = { "Il conciatore eremita", "Porta il Bundle of Hides all'eremita sulla cresta che domina le Dry Hills, nelle Barrens.", "Queste pelli sono destinate a un conciatore con cui commercio spesso. È una specie di eremita e vive da solo in cima alla cresta dietro di me. Arrampicarmi su per un pendio ripido non è qualcosa che riesco a fare facilmente adesso, quindi ti sarei debitore se potessi fare questa consegna per me.\n\nAh, e riguardo all'aspetto di questo conciatore... non devi allarmarti. Nonostante l'aspetto, non è una minaccia. Te lo giuro.", "Salute, {class}. Cosa ti porta oggi fin quassù, nella mia proprietà?", nil, 0xc91f6041, 0x2e6fcebc, 0xf3a9275e, 0xbe27a510, nil, "....m" },
  [95507] = { "La selvaggina di Vrang", "Raccogli 8 Trapped Game dalle trappole che si trovano a Sprung Traps, nelle Barrens.", "Già che sei là fuori, mi saresti di grande aiuto se controllassi le mie trappole. Le ho sparse per tutta la valle.\n\nRiporta la piccola selvaggina che ho catturato. Ma tieni d'occhio gli altri animali selvatici. Questa zona può essere pericolosa se non stai <attento/attenta>.", nil, nil, 0x56a6a9a8, 0xc7e5f7a1, 0xd203b57b, nil, nil, "...mm" },
  [95534] = { "Il mistero di Strahnbrad", "Risolvi il mistero di Strahnbrad e riferisci ciò che hai scoperto in città, a Hillsbrad.", "<Il biglietto è bruciacchiato in alcuni punti, ma si legge ancora.>\n\nSi dice che quei vecchi mantici abbiano una volontà propria e si animino quando nessuno guarda. Non m'importa se è una storia di fantasmi, faresti meglio ad andare fino in fondo prima del mio ritorno.\n\nA Strahnbrad c'è un grande potere, lo so.\n\n<Il resto del biglietto è bruciacchiato e strappato, come bruciato da una magia del fuoco.>", nil, nil, 0x84d1d4cf, 0xe5975afe, 0x53e7de0b, nil, nil, "...mm" },
  [95646] = { "Orrori nelle Highland", "Uccidi un Highland Horror negli Excavation Sites e porta il suo nucleo di radice a Rethiel the Greenwarden, nelle Wetlands.", "Queste paludi salmastre contengono una riserva più grande di acque dolci meridionali. Mi addolora, eppure nelle mie radici sento una corruzione che filtra attraverso quella gola di montagna.\n\nLe creature, come quelle delle nostre pianure, reagiscono più aspramente alla contaminazione. Prive fin dall'alba della vita del sale marino che le tempra, hanno poca forza contro un tale male.\n\nVa' su quegli altipiani e portami il nucleo di radice dell'Highland Horror.", nil, nil, 0x79650957, 0x81ee8465, 0xbce12a7e, nil, nil, "...mm" },
  [95663] = { "Voci sui Dragonmaw", "Recati nelle Wetlands e incontra il Deathstalker Agent sulle colline sopra l'accampamento dei Dragonmaw.", "I Dragonmaw sono un clan temibile.\n\nSono noti per magie di vincolo abbastanza forti da far servire i draghi, e si dice che stiano preparando una qualche dimostrazione nelle Wetlands. Che sia verità o spacconata, i Deathstalker non possono agire su sussurri appena abbozzati. Simboli frammentari mi hanno portato solo questo.\n\nUn'agente deathstalker ha bisogno di una mano sulle colline sopra l'accampamento dei Dragonmaw. Incontrala lì. Ti rivelerà i passi successivi.", nil, nil, 0xecfb9de3, 0x607aac05, 0x19f544b5, nil, nil, "...mm" },
  [95737] = { "In cerca di Caitlin", "Parla con Caitlin Grassman, a Menethil Harbor.", "Di tanto in tanto corrispondo con altri del mio mestiere: erboristi o eccentrici che studiano piante rare e stranezze locali. Ci scambiamo scoperte, e a volte avvertimenti su ciò che ci attende.\n\nUn'alchimista delle Wetlands mi ha scritto di una squadra di scavo di cui faceva parte suo marito, che aveva scoperto tracce di un'erba primordiale perduta da tempo... ma non mi ha mai fatto sapere quanta ce ne fosse o quanto fosse accessibile.\n\nSe puoi, va' a vedere come sta Caitlin Grassman, a Menethil Harbor.", nil, nil, 0xf6e09b80, 0x29283070, 0xb0744041, nil, nil, "...mm" },
  [95772] = { "La ricerca di Songblade", "Cerca il fratello di Dorin Songblade, Daewyn, al Whelgar's Excavation Site.", "Mio fratello ha cercato di trascinarmi nelle Wetlands con una squadra di scavo di Loch Modan. Diceva che andavano su colline dove nessun nano ha mai messo piede, per una specie di scavo.\n\nSì, ci sarei andato, se non fossi già in ritardo con questa pila di cinture da sistemare.\n\nDi solito però Daewyn scrive dopo essere partito. Non ho sentito niente, e stavolta ho una strana sensazione.\n\nSe vai da quelle parti, ti dispiacerebbe controllare come sta mio fratello?", nil, nil, 0x4225ee40, 0x72145fde, 0x91fbce45, nil, nil, "...mm" },
  [95795] = { "Caduto nella palude", "Torna da Dorin Songblade.", "<Copri il corpo del nano con il suo mantello.>\n\nRecati a Lakeshire e informa di persona Dorin Songblade di cosa è successo a suo fratello negli Excavation Sites.", nil, nil, 0xbfc85885, 0x2739cdb1, 0x9e5ae38b, nil, nil, "...mm" },
  [95809] = { nil, "Torna da Caitlin Grassman, a Menethil Harbor.", "Ho bisogno di un momento di riposo prima di trovare da solo la via d'uscita.\n\n<Tira fuori alcune canne dallo zaino e le intreccia e piega rapidamente a forma di cuore.>\n\nPrendi questo e portalo a Caitlin. Dille che tornerò presto a casa! Ora che grazie a te abbiamo un sentiero libero, raccoglierò i miei fasci e seguirò le tue tracce.\n\nGrazie.", nil, nil, nil, 0xb6ab7769, 0x84c0de8c, nil, nil, "m..mm" },
  [95810] = { "Trasporto della reliquia perduta", "Porta la Titan Relic al Prospector Whelgar, al sito di scavo delle Wetlands.", "Raccogli un frammento dell'automa meccanico di roccia. Ha una consistenza diversa da qualsiasi cosa tu abbia mai toccato, un materiale composito di natura sconosciuta. Questo è sicuramente più \"congegno\" che \"detrito\".\n\nIl Prospector Whelgar in persona, al suo sito di scavo, potrebbe avere qualcosa di utile da dirti sulla reliquia.", nil, nil, 0x66a19050, 0x25ed1b64, 0x09d52652, nil, nil, "...mm" },
  [95816] = { "Iscrivetemi!", "Porta il modulo compilato a Elaine Compton, nelle Redridge Mountains.", "Salute, <stimato/stimata> <artigiano/artigiana>!\n\nLa compilazione di questo modulo ti concederà il permesso non esclusivo, revocabile e legalmente limitato di esporre insegne pubblicitarie per i tuoi mestieri in tutta Azeroth!\n\nUna volta compilato, porta questo modulo al Contract Coordinator della tua filiale locale dell'Azeroth Commerce Authority per avviare la pratica.\n\nBuon lavoro!", nil, nil, 0xe71188a6, 0xaef04737, 0x5eb40123, nil, nil, "...mm" },
  [95817] = { nil, "Incontra Rotgath Stonebeard vicino alla Great Forge, a Ironforge.", "Hai mai conosciuto Rotgath Stonebeard? È un fabbro nanico di Ironforge. Non è il tipo più chiacchierone in giro, ma è sempre affidabile. Ci rivolgiamo spesso a lui quando ci servono lavori in serie dal design semplice, quelli che Stondry è troppo orgoglioso per fare di persona.\n\nI suoi tempi di consegna sono ottimi, soprattutto quando si tratta di aiutare i nuovi artigiani ad avviare la loro bottega. Non mi fiderei di nessun altro per farti fare l'insegna in fretta. Digli che ti mando io, se ti dà problemi!", nil, nil, nil, 0x29aa8c0c, 0x265b4cd5, nil, nil, "m..mm" },
  [95818] = { "Un lavoretto veloce", "Porta i materiali richiesti a Rotgath Stonebeard, vicino alla Great Forge, a Ironforge.", "Possiamo sistemarti e mandarti via in un attimo, purché tu abbia i materiali! Ci serviranno $N1 Mithril Bars e $N2 Heavy Leather. Di solito servono anche altri metalli e simili, ma ho degli scarti che occupano spazio e che possiamo usare per quei pezzi in più.\n\nAh, come favore personale, ti chiederò anche $N3 Goldthorn. Mia moglie conosce un'ottima ricetta per il tè e vorrei farle una sorpresa. Consideralo il tuo pagamento!", nil, nil, 0xae19085c, 0x93f08152, 0x8ce5bacd, nil, nil, "...mm" },
  [95819] = { "Iscrivetemi!", nil, nil, nil, nil, 0xe71188a6, nil, nil, nil, nil, ".mmmm" },
  [95999] = { nil, nil, nil, "Cos'hai lì, {race}?", nil, nil, nil, nil, 0x46dc827d, nil, "mmm.m" },
})
